  const schema = {
    type: "OBJECT",
    properties: {
      pages: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            page: { type: "INTEGER" },
            labels: { type: "ARRAY", items: { type: "STRING", enum: ["eligibility", "boq", "other"] } },
          },
          required: ["page", "labels"],
