// Builds the 4 Gemini requests and reads their answers. The AI only reads the tender;
// every decision is made afterwards by plain code. Each prompt asks for exact quotes so
// verifyQuotes can prove them, and says to leave a value null rather than guess.

const GEMINI_MODEL = "gemini-3-flash-preview";
const CLASSIFY_CHARS_PER_PAGE = 1500;
const MAX_PAGES_PER_CALL = 40;

const RULES_FOR_AI =
  "Rules: answer only from the pages given. Copy every quote EXACTLY as printed (same words, same order, " +
  "max 40 words) from the page you cite. If something isn't stated, leave it null; never guess or infer.";

function pagesBlock(pages, maxChars) {
  return pages
    .map((p) => "=== PAGE " + p.page + " ===\n" + (maxChars ? p.text.slice(0, maxChars) : p.text))
    .join("\n\n");
}

function geminiRequest(prompt, input, schema) {
  return {
    model: GEMINI_MODEL,
    body: {
      contents: [{ role: "user", parts: [{ text: prompt + "\n\n" + input }] }],
      generationConfig: {
        responseMimeType: "application/json",
        responseSchema: schema,
        thinkingConfig: { thinkingLevel: "low" },
      },
    },
  };
}

const S = {
  str: { type: "STRING" },
  strOrNull: { type: "STRING", nullable: true },
  numOrNull: { type: "NUMBER", nullable: true },
  intOrNull: { type: "INTEGER", nullable: true },
  boolOrNull: { type: "BOOLEAN", nullable: true },
};

// A1: label every page, using only the start of each page to stay fast.
function classifyRequest(pages) {
  const prompt =
    "You are reading an Indian government tender (GeM / CPPP / state portal) for electrical or solar work. " +
    "Label each page: 'eligibility' if it states bidder qualification or bid conditions (EMD, turnover, past " +
    "experience, OEM/manufacturer authorization, certificates, MSE exemption, approved makes/brands); 'boq' if it " +
    "contains Bill of Quantities / schedule of items with quantities; otherwise 'other'. A page can have more " +
    "than one label. Return every page number given.";
  const schema = {
    type: "OBJECT",
    properties: {
      pages: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            page: { type: "INTEGER" },
            labels: { type: "ARRAY", items: { type: "STRING", enum: ["eligibility", "boq", "other"] } },
          },
          required: ["page", "labels"],
        },
      },
    },
    required: ["pages"],
  };
  return geminiRequest(prompt, pagesBlock(pages, CLASSIFY_CHARS_PER_PAGE), schema);
}

// Pages the AI labelled, plus pages whose text contains a keyword (a safety net in case
// the classifier missed one), in page order, capped so the call stays fast.
function pickPages(pages, classified, label, keywords) {
  const labelled = new Set(
    ((classified && classified.pages) || []).filter((p) => (p.labels || []).includes(label)).map((p) => p.page),
  );
  const picked = pages.filter((p) => labelled.has(p.page) || keywords.test(p.text));
  return picked.slice(0, MAX_PAGES_PER_CALL);
}

const ELIGIBILITY_KEYWORDS = /turnover|e\.?m\.?d|earnest money|bid security|experience|authori[sz]ation|\bmaf\b|iso\s?\d|certificat|\bmse\b|approved make|list of makes/i;
const BOQ_KEYWORDS = /bill of quantit|\bboq\b|schedule of (items|quantit|requirement)|price schedule/i;

// Every field in the AI's answer is REQUIRED (null when it doesn't apply). Gemini quietly
// drops optional fields on long inputs, which lost quantities, EMD amounts and order values.
// So each clause is one flat object with every field present; toClauses() reshapes it.
const CLAUSE_FIELDS = {
  type: { type: "STRING", enum: ["emd", "turnover", "experience", "oem_authorization", "certificate", "mse_exemption", "approved_makes"] },
  requirement: S.str,
  page: S.intOrNull,
  quote: S.strOrNull,
  makes: { type: "ARRAY", items: S.str },
  emdRequired: S.boolOrNull,
  emdAmountInr: S.numOrNull,
  minAvgAnnualTurnoverInr: S.numOrNull,
  notRequired: S.boolOrNull,
  experienceYears: S.numOrNull,
  lookbackYears: S.numOrNull,
  orderOptions: {
    type: "ARRAY",
    items: {
      type: "OBJECT",
      properties: { count: { type: "INTEGER" }, eachAtLeastInr: { type: "NUMBER" } },
      required: ["count", "eachAtLeastInr"],
    },
  },
  oemRequired: S.boolOrNull,
  certificateName: S.strOrNull,
  mseExemptExperienceTurnover: S.boolOrNull,
  mseExemptEmd: S.boolOrNull,
  itemGroups: {
    type: "ARRAY",
    items: {
      type: "OBJECT",
      properties: { itemGroup: S.str, brands: { type: "ARRAY", items: S.str } },
      required: ["itemGroup", "brands"],
    },
  },
};

// Kinds of documents a tender can ask the bidder to submit (Bid Readiness checklist).
const DOC_TYPES = [
  "oem_authorization", "turnover_evidence", "experience_evidence", "emd_or_bid_security", "gst_registration",
  "pan_card", "udyam_registration", "bis_certificate", "iso_certificate", "type_test_report", "technical_datasheet",
  "local_content_declaration", "signed_annexure", "electrical_licence", "other",
];

const DOCUMENT_FIELDS = {
  docType: { type: "STRING", enum: DOC_TYPES },
  name: S.str,
  requirement: { type: "STRING", enum: ["required", "conditional"] },
  condition: S.strOrNull,
  page: S.intOrNull,
  quote: S.strOrNull,
};

// A2: find the eligibility clauses with normalized values, page and exact quote, and the
// documents the bidder must submit.
function eligibilityRequest(pages, classified) {
  const prompt =
    "Extract the bidder eligibility clauses from these tender pages. Clause types and the fields to fill:\n" +
    "- emd: earnest money / bid security. emdRequired (false only if the tender says no EMD), emdAmountInr.\n" +
    "- turnover: minimum average annual turnover. minAvgAnnualTurnoverInr in rupees (1 lakh = 100000, 1 crore = 10000000). notRequired=true only if the tender explicitly says none.\n" +
    "- experience: experienceYears = minimum years the bidder must have been doing similar work. orderOptions = every " +
    "'N similar works/orders each of at least ₹X' option, e.g. [{count:3, eachAtLeastInr:2000000}, {count:1, eachAtLeastInr:4000000}]. " +
    "lookbackYears = the period in which those works must have been completed ('during the last 7 years' → 7). " +
    "A look-back period is NOT experienceYears: leave experienceYears null unless the tender asks for N years of experience.\n" +
    "- oem_authorization: manufacturer/OEM authorization (MAF). oemRequired.\n" +
    "- certificate: one clause per required certificate/licence (ISO, BIS, electrical licence…). certificateName.\n" +
    "- mse_exemption: whether MSEs are exempted. mseExemptExperienceTurnover and mseExemptEmd as true/false, null if not stated.\n" +
    "- approved_makes: itemGroups = one object per item group: itemGroup = the item name only (e.g. \"MCCB\"), brands = each brand as a separate string.\n" +
    "Every field must be present: use null (or [] for lists) when it doesn't apply to the clause type. Return exactly " +
    "one clause each for emd, turnover, experience and oem_authorization (if present); certificate, mse_exemption and " +
    "approved_makes may repeat. makes = every manufacturer/brand name in the quote ([] if none).\n" +
    "Also list in documents[] every document the tender explicitly asks the bidder to submit or upload (MAF/OEM " +
    "authorization, turnover or CA certificate, experience proof such as purchase orders or completion certificates, " +
    "EMD or bid security declaration, GST, PAN, Udyam, BIS or ISO certificates, type-test reports, datasheets, local " +
    "content declaration, signed annexures/undertakings/forms, electrical licence…). requirement = 'conditional' when " +
    "the tender says it applies only in some cases (condition = that case, e.g. 'if the bidder is not the OEM'); " +
    "otherwise 'required'. Only list documents the tender actually asks for; never assume a standard list. " +
    RULES_FOR_AI;
  const schema = {
    type: "OBJECT",
    properties: {
      clauses: { type: "ARRAY", items: { type: "OBJECT", properties: CLAUSE_FIELDS, required: Object.keys(CLAUSE_FIELDS) } },
      documents: { type: "ARRAY", items: { type: "OBJECT", properties: DOCUMENT_FIELDS, required: Object.keys(DOCUMENT_FIELDS) } },
    },
    required: ["clauses", "documents"],
  };
  return geminiRequest(prompt, pagesBlock(pickPages(pages, classified, "eligibility", ELIGIBILITY_KEYWORDS)), schema);
}

// Reshapes A2's flat answer into the { type, requirement, values, makes, page, quote } clauses
// the rules read. Clauses already in that shape (e.g. the demo's) pass through unchanged.
function toClauses(answer) {
  return ((answer && answer.clauses) || []).map((c) => {
    if (c.values) return c;
    const values = {
      required: c.type === "emd" ? c.emdRequired : c.type === "oem_authorization" ? c.oemRequired : null,
      amountInr: c.emdAmountInr,
      minAvgAnnualInr: c.minAvgAnnualTurnoverInr,
      notRequired: c.notRequired,
      years: c.experienceYears,
      lookbackYears: c.lookbackYears,
      orderOptions: c.orderOptions,
      name: c.certificateName,
      experienceAndTurnover: c.mseExemptExperienceTurnover,
      emd: c.mseExemptEmd,
      items: c.itemGroups,
    };
    return { type: c.type, requirement: c.requirement, values: values, makes: c.makes || [], page: c.page, quote: c.quote };
  });
}

// A3: pull out the BOQ lines.
function boqRequest(pages, classified) {
  const prompt =
    "Extract every line item of the Bill of Quantities (BOQ / schedule of items) from these tender pages. " +
    "For each line: item number as printed, full description (join wrapped lines), unit, quantity (qty), and the " +
    "rate and amount if printed (null if not). Every field must be present. page = where the line starts; quote = " +
    "the exact printed text of the line's first few words of description (max 15 words). Skip headings and totals. " +
    RULES_FOR_AI;
  const schema = {
    type: "OBJECT",
    properties: {
      rows: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            item: S.str,
            description: S.str,
            unit: S.strOrNull,
            qty: S.numOrNull,
            rate: S.numOrNull,
            amount: S.numOrNull,
            page: S.intOrNull,
            quote: S.strOrNull,
          },
          required: ["item", "description", "unit", "qty", "rate", "amount", "page", "quote"],
        },
      },
    },
    required: ["rows"],
  };
  return geminiRequest(prompt, pagesBlock(pickPages(pages, classified, "boq", BOQ_KEYWORDS)), schema);
}

// A4: choose a SKU for each BOQ line, only from that line's shortlist.
function matchRequest(boqRows, shortlist) {
  const byItem = new Map(shortlist.map((s) => [String(s.item), s.candidates]));
  const lines = boqRows
    .filter((r) => (byItem.get(String(r.item)) || []).length > 0)
    .map((r) => ({
      item: r.item,
      description: r.description,
      unit: r.unit,
      candidates: byItem.get(String(r.item)).map((c) => ({ sku: c.sku, description: c.description, brand: c.brand, unit: c.unit })),
    }));
  const prompt =
    "Match each tender BOQ line to the supplier SKU that is the same product. Choose ONLY from that line's " +
    "candidates. Ratings must match exactly (amps, poles, kA, cores, sq mm, watts). If no candidate is the same " +
    "product, return sku null. confidence: 0 to 1, how sure you are it's the same product. reason: one short line.";
  const schema = {
    type: "OBJECT",
    properties: {
      matches: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: { item: S.str, sku: S.strOrNull, confidence: { type: "NUMBER" }, reason: S.str },
          required: ["item", "sku", "confidence", "reason"],
        },
      },
    },
    required: ["matches"],
  };
  return { lineCount: lines.length, request: geminiRequest(prompt, JSON.stringify(lines), schema) };
}

// Document requirements from A2, checked into a fixed shape: unknown types become "other",
// anything without a name is dropped. (The AI's output is never trusted as-is.)
function toDocRequirements(answer) {
  return ((answer && answer.documents) || [])
    .filter((d) => d && typeof d.name === "string" && d.name.trim())
    .map((d) => ({
      docType: DOC_TYPES.includes(d.docType) ? d.docType : "other",
      name: d.name.trim().slice(0, 120),
      requirement: d.requirement === "conditional" ? "conditional" : "required",
      condition: typeof d.condition === "string" && d.condition.trim() ? d.condition.trim().slice(0, 200) : null,
      page: Number.isInteger(d.page) ? d.page : null,
      quote: typeof d.quote === "string" && d.quote.trim() ? d.quote : null,
    }));
}

// Fields read from a supporting document (MAF letter, certificate, purchase order…).
const SUPPORT_FIELDS = ["issuer", "holder", "manufacturer", "productCategories", "tenderReference", "territory", "issueDate", "validUntil", "signatory", "certificateNumber", "standard"];

// A6: read the bidder's supporting documents (only those with readable text). docs:
// [{ name, pages: [{page, text}] }]. Each field needs an exact quote so code can check it.
function supportingDocsRequest(docs) {
  const input = docs
    .map((d, i) => `##### DOCUMENT ${i + 1}: ${d.name}\n` + d.pages.map((p) => `=== PAGE ${p.page} ===\n${p.text.slice(0, 6000)}`).join("\n\n"))
    .join("\n\n");
  const prompt =
    "These are documents a bidder plans to submit with an Indian government tender. For each DOCUMENT n, give " +
    "docIndex = n, docType (what it is; 'other' if none fit), title, and these fields when the document states them " +
    "(null when it doesn't): issuer (who issued it), holder (who it is issued to / the authorized dealer or bidder), " +
    "manufacturer (the OEM, for authorization letters), productCategories (products or product families covered), " +
    "tenderReference (bid/tender number it is specific to), territory, issueDate and validUntil (as YYYY-MM-DD), " +
    "signatory (name and designation of who signed), certificateNumber, standard (e.g. ISO 9001:2015, IS 694). " +
    "For every non-null field add one evidence entry {field, page, quote} with the exact words from that document " +
    "that state it. Never infer a date, name or scope that isn't written. " +
    RULES_FOR_AI;
  const schema = {
    type: "OBJECT",
    properties: {
      documents: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            docIndex: { type: "INTEGER" },
            docType: { type: "STRING", enum: DOC_TYPES },
            title: S.strOrNull,
            issuer: S.strOrNull,
            holder: S.strOrNull,
            manufacturer: S.strOrNull,
            productCategories: { type: "ARRAY", items: S.str },
            tenderReference: S.strOrNull,
            territory: S.strOrNull,
            issueDate: S.strOrNull,
            validUntil: S.strOrNull,
            signatory: S.strOrNull,
            certificateNumber: S.strOrNull,
            standard: S.strOrNull,
            evidence: {
              type: "ARRAY",
              items: { type: "OBJECT", properties: { field: { type: "STRING", enum: SUPPORT_FIELDS }, page: S.intOrNull, quote: S.strOrNull }, required: ["field", "page", "quote"] },
            },
          },
          required: ["docIndex", "docType", "title", ...SUPPORT_FIELDS, "evidence"],
        },
      },
    },
    required: ["documents"],
  };
  return geminiRequest(prompt, input, schema);
}

// A6's answer checked into a fixed shape, keyed to the uploaded files by docIndex.
function toSupportingDocs(answer, docCount) {
  const str = (v) => (typeof v === "string" && v.trim() ? v.trim().slice(0, 300) : null);
  const date = (v) => (typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v.trim()) ? v.trim() : null);
  return ((answer && answer.documents) || [])
    .filter((d) => d && Number.isInteger(d.docIndex) && d.docIndex >= 1 && d.docIndex <= docCount)
    .map((d) => ({
      docIndex: d.docIndex,
      docType: DOC_TYPES.includes(d.docType) ? d.docType : "other",
      title: str(d.title),
      issuer: str(d.issuer),
      holder: str(d.holder),
      manufacturer: str(d.manufacturer),
      productCategories: Array.isArray(d.productCategories) ? d.productCategories.map(str).filter(Boolean).slice(0, 20) : [],
      tenderReference: str(d.tenderReference),
      territory: str(d.territory),
      issueDate: date(d.issueDate),
      validUntil: date(d.validUntil),
      signatory: str(d.signatory),
      certificateNumber: str(d.certificateNumber),
      standard: str(d.standard),
      evidence: (Array.isArray(d.evidence) ? d.evidence : [])
        .filter((e) => e && SUPPORT_FIELDS.includes(e.field) && Number.isInteger(e.page) && typeof e.quote === "string")
        .map((e) => ({ field: e.field, page: e.page, quote: e.quote })),
    }));
}

// Reads the JSON answer out of a Gemini response; throws a readable error if there isn't one.
function readGeminiJson(response, step) {
  const cand = response && response.candidates && response.candidates[0];
  const text = cand && cand.content && (cand.content.parts || []).map((p) => p.text || "").join("");
  if (!text) {
    const why = (cand && cand.finishReason) || (response && response.promptFeedback && response.promptFeedback.blockReason) || "empty answer";
    throw new Error(step + ": the AI gave no answer (" + why + ")");
  }
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error(step + ": the AI's answer was not valid JSON");
  }
}


const body = $('Webhook').first().json.body;
const readable = (body.supportingDocs || []).filter((d) => !d.unreadable);
return [{ json: supportingDocsRequest(readable.length ? readable : [{ name: 'none', pages: [{ page: 1, text: '(no documents uploaded)' }] }]) }];

// Checks that every quote the AI gave really appears on the page it cited.
// Plain script: pasted as-is into an n8n Code node and loaded the same way by the tests.

// Lowercase, unify quote marks and dashes, keep only letters/digits as space-separated words.
function normalizeForQuote(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[‘’‚‛′]/g, "'")
    .replace(/[“”„″]/g, '"')
    .replace(/[‐-―]/g, "-")
    .replace(/[^a-z0-9ऀ-ॿ]+/g, " ")
    .trim();
}

function wordTrigrams(words) {
  const grams = new Set();
  for (let i = 0; i + 2 < words.length; i++) grams.add(words[i] + " " + words[i + 1] + " " + words[i + 2]);
  return grams;
}

// True when the quote is on the page: exact match after normalizing, or (for quotes of
// 6+ words) at least 90% of the quote's word triples appear on the page.
function quoteOnText(quote, pageText) {
  const q = normalizeForQuote(quote);
  const p = normalizeForQuote(pageText);
  if (!q || !p) return false;
  if (p.includes(q)) return true;
  const qWords = q.split(" ");
  if (qWords.length < 6) return false;
  const qGrams = wordTrigrams(qWords);
  const pGrams = wordTrigrams(p.split(" "));
  let hits = 0;
  qGrams.forEach((g) => { if (pGrams.has(g)) hits++; });
  return hits / qGrams.size >= 0.9;
}

// pages: [{ page, text }]. Returns { verified, note }.
// A quote that runs over a page break may span the cited page and the next one.
function verifyQuote(pages, page, quote) {
  if (page == null || !quote || !String(quote).trim()) {
    return { verified: false, note: "No page or quote given" };
  }
  const byPage = new Map(pages.map((p) => [p.page, p.text]));
  if (!byPage.has(page)) return { verified: false, note: "Page " + page + " does not exist in this PDF" };
  const here = byPage.get(page);
  const next = byPage.get(page + 1) || "";
  if (quoteOnText(quote, here)) return { verified: true, note: null };
  // Spanning counts only if the quote really crosses the break, not if it's wholly on the next page.
  if (quoteOnText(quote, here + " " + next) && !quoteOnText(quote, next)) return { verified: true, note: null };
  for (const p of pages) {
    if (p.page !== page && quoteOnText(quote, p.text)) {
      return { verified: false, note: "Quote is on page " + p.page + ", not page " + page };
    }
  }
  return { verified: false, note: "Quote not found on page " + page };
}

// Units as printed in BOQs, followed by the quantity: "Nos | 120", "Mtr 600", "Set: 1".
const UNIT_QTY = /(?:^|[\s|:,])(nos?|numbers?|each|sets?|mtrs?|metres?|meters?|rmt|rm|m|kg|lot|job|sqm|cum|ltrs?|pairs?)\.?\s*[|:]?\s*(\d[\d,]*(?:\.\d+)?)(?![\d.]*\s*(?:mm|sq|kv|ka|w|a)\b)/i;

// Same normalization as normalizeForQuote, plus where each normalized character came from in
// the raw text, so a quote found in normalized text can be located in the original.
function normalizeWithMap(text) {
  const raw = String(text || "");
  let norm = "";
  const map = [];
  for (let i = 0; i < raw.length; i++) {
    const ch = normalizeForQuote(raw[i]);
    if (ch) {
      norm += ch;
      map.push(i);
    } else if (norm && norm[norm.length - 1] !== " ") {
      norm += " ";
      map.push(i);
    }
  }
  return { norm: norm, map: map };
}

// Plain-code reading of a verified BOQ line: finds where the AI's quote sits on the page and
// reads the unit and quantity printed right after the description. Short quotes can start
// several lines ("LT XLPE ... cable 3.5 core"), so each place is scored by how well the printed
// description after it matches the AI's full description; a tie means we can't tell, and
// nothing is read. Returns null if the line can't be pinned down or has no unit + number.
function readBoqLine(pageText, quote, description) {
  const q = normalizeForQuote(quote);
  if (!q) return null;
  const raw = String(pageText);
  const { norm, map } = normalizeWithMap(raw);
  const wanted = new Set(normalizeForQuote(description || quote).split(" "));
  const found = [];
  for (let at = norm.indexOf(q); at >= 0; at = norm.indexOf(q, at + 1)) {
    // Whole words only ("6a" must not match inside "16a").
    if (at > 0 && norm[at - 1] !== " ") continue;
    const end = map[at + q.length - 1] + 1;
    const m = raw.slice(end, end + 250).match(UNIT_QTY);
    if (!m) continue;
    const between = normalizeForQuote(raw.slice(end, end + m.index)).split(" ").filter(Boolean);
    const score = between.filter((w) => wanted.has(w)).length - between.filter((w) => !wanted.has(w)).length;
    found.push({ score: score, unit: m[1], qty: Number(m[2].replace(/,/g, "")) });
  }
  if (found.length === 0) return null;
  found.sort((a, b) => b.score - a.score);
  if (found.length > 1 && found[0].score === found[1].score && found[0].qty !== found[1].qty) return null;
  return { unit: found[0].unit, qty: found[0].qty };
}

// For each verified BOQ row: fill a missing quantity/unit from the printed line, and mark a
// row whose AI quantity disagrees with the page (kept for checkMatches to flag red).
function readBoqLines(pages, rows) {
  const byPage = new Map(pages.map((p) => [p.page, p.text]));
  return (rows || []).map((r) => {
    if (!r.verified) return r;
    const text = (byPage.get(r.page) || "") + "\n" + (byPage.get(r.page + 1) || "");
    const printed = readBoqLine(text, r.quote, r.description);
    if (!printed) return r;
    const out = Object.assign({}, r);
    if (out.qty == null) out.qty = printed.qty;
    else if (Math.abs(out.qty - printed.qty) > 1e-9) out.qtyMismatch = printed.qty;
    if (!out.unit) out.unit = printed.unit;
    return out;
  });
}

// Adds `verified` and `verifyNote` to each item that has { page, quote }.
function verifyQuotes(pages, items) {
  return (items || []).map((item) => {
    const check = verifyQuote(pages, item.page, item.quote);
    return Object.assign({}, item, { verified: check.verified, verifyNote: check.note });
  });
}


// Decides pass / fail / unknown for each eligibility clause, comparing the tender's
// requirement with the firm profile. The AI only extracted the clauses; every decision here
// is a plain comparison. Golden rule: a clause without a verified page + quote is never "pass".

const CORE_CLAUSES = ["emd", "turnover", "experience", "oem_authorization"];

const CLAUSE_LABELS = {
  emd: "EMD (bid security)",
  turnover: "Minimum turnover",
  experience: "Past experience",
  oem_authorization: "OEM authorization (MAF)",
  certificate: "Certificate",
  mse_exemption: "MSE exemption",
  approved_makes: "Approved makes",
};

function formatInr(n) {
  if (typeof n !== "number" || !isFinite(n)) return "?";
  if (n >= 1e7) return "₹" + +(n / 1e7).toFixed(2) + " crore";
  if (n >= 1e5) return "₹" + +(n / 1e5).toFixed(2) + " lakh";
  return "₹" + n.toLocaleString("en-IN");
}

function isNum(n) {
  return typeof n === "number" && isFinite(n);
}

function sameName(a, b) {
  const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  const x = norm(a);
  const y = norm(b);
  return !!x && !!y && (x.includes(y) || y.includes(x));
}

function stillValid(validUntil, today) {
  return validUntil == null || validUntil >= today;
}

function row(clause, result, firmHas, reason) {
  return {
    type: clause.type,
    label: CLAUSE_LABELS[clause.type] || clause.type,
    requirement: clause.requirement || null,
    firmHas: firmHas,
    result: result,
    reason: reason,
    page: clause.page == null ? null : clause.page,
    quote: clause.quote || null,
  };
}

// Reads the tender's MSE exemption clauses. Tenders often state the experience/turnover and
// EMD exemptions in separate lines, so each one comes from whichever verified clause says it.
function mseExemptions(clauses) {
  const verified = clauses.filter((x) => x.type === "mse_exemption" && x.verified);
  const grants = (key) => verified.find((c) => c.values && c.values[key] === true) || null;
  return { experienceAndTurnover: grants("experienceAndTurnover"), emd: grants("emd") };
}

const NUMBER_WORDS = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };

// "during the last seven years" sets a look-back window for past works, not a minimum
// experience. True when `years` is just that window.
function isLookbackYears(c, years) {
  const v = c.values || {};
  if (v.lookbackYears === years) return true;
  const m = String(c.quote || "").toLowerCase().match(/(?:during|in|within)\s+the\s+(?:last|preceding|past)\s+(\d+|[a-z]+)\s+(?:\(\w+\)\s+)?years?/);
  if (!m) return false;
  return (/^\d+$/.test(m[1]) ? Number(m[1]) : NUMBER_WORDS[m[1]]) === years;
}

function checkTurnover(c, firm, exempt) {
  const v = c.values || {};
  const has = formatInr(firm.avgAnnualTurnoverInr) + " average";
  if (v.notRequired === true) return row(c, "pass", has, "Tender sets no turnover requirement");
  if (!isNum(v.minAvgAnnualInr)) return row(c, "unknown", has, "Turnover amount could not be read from the tender");
  if (firm.avgAnnualTurnoverInr >= v.minAvgAnnualInr) {
    return row(c, "pass", has, "Firm turnover meets " + formatInr(v.minAvgAnnualInr));
  }
  if (exempt && firm.isMSE) {
    return row(c, "pass", has, "Below " + formatInr(v.minAvgAnnualInr) + ", but the tender exempts MSEs (p. " + exempt.page + ")");
  }
  return row(c, "fail", has, "Needs " + formatInr(v.minAvgAnnualInr) + ", firm has " + formatInr(firm.avgAnnualTurnoverInr));
}

// Experience comes as years in business and/or "N orders of at least ₹X each" options;
// meeting any one option is enough.
function checkExperience(c, firm, exempt) {
  const v = c.values || {};
  const orders = firm.pastOrders || [];
  const has = firm.yearsOfExperience + " years, " + orders.length + " past orders";
  if (v.notRequired === true) return row(c, "pass", has, "Tender sets no experience requirement");
  const options = Array.isArray(v.orderOptions) ? v.orderOptions.filter((o) => isNum(o.count) && isNum(o.eachAtLeastInr)) : [];
  const years = isNum(v.years) && !isLookbackYears(c, v.years) ? v.years : null;
  if (years == null && options.length === 0) {
    return row(c, "unknown", has, "Experience requirement could not be read from the tender");
  }
  const problems = [];
  if (years != null && firm.yearsOfExperience < years) {
    problems.push("needs " + years + " years, firm has " + firm.yearsOfExperience);
  }
  if (options.length > 0) {
    const met = options.some((o) => orders.filter((x) => x.valueInr >= o.eachAtLeastInr).length >= o.count);
    if (!met) {
      problems.push("needs " + options.map((o) => o.count + " order(s) of " + formatInr(o.eachAtLeastInr)).join(" or "));
    }
  }
  if (problems.length === 0) return row(c, "pass", has, "Firm meets the experience requirement");
  if (exempt && firm.isMSE) {
    return row(c, "pass", has, "Short (" + problems.join("; ") + "), but the tender exempts MSEs (p. " + exempt.page + ")");
  }
  return row(c, "fail", has, problems.join("; "));
}

// EMD is money the firm deposits, so it isn't a fail; "pass" means the firm can comply,
// and the reason says what to arrange.
function checkEmd(c, firm, exempt) {
  const v = c.values || {};
  const has = firm.isMSE ? "Registered MSE" : "Not an MSE";
  if (v.required === false) return row(c, "pass", has, "No EMD required");
  if (exempt && firm.isMSE) return row(c, "pass", has, "EMD exempt for MSEs (p. " + exempt.page + ")");
  if (!isNum(v.amountInr)) return row(c, "unknown", has, "EMD amount could not be read from the tender");
  return row(c, "pass", has, "Arrange EMD of " + formatInr(v.amountInr));
}

function checkOem(c, firm, today) {
  const v = c.values || {};
  const mafs = firm.oemAuthorizations || [];
  const has = mafs.length ? mafs.map((m) => m.brand + (stillValid(m.validUntil, today) ? "" : " (expired)")).join(", ") : "None";
  if (v.required === false) return row(c, "pass", has, "No OEM authorization required");
  if (v.required !== true) return row(c, "unknown", has, "Could not tell whether OEM authorization is required");
  // Brands from values.brands, or else the AI's `makes` — kept only if the name really
  // appears in the clause's verified quote.
  const inQuote = (m) => sameName(m, m) && String(c.quote || "").toLowerCase().replace(/[^a-z0-9]/g, "").includes(String(m).toLowerCase().replace(/[^a-z0-9]/g, ""));
  const listed = Array.isArray(v.brands) && v.brands.length ? v.brands : (Array.isArray(c.makes) ? c.makes : []).filter(inQuote);
  const brands = listed.filter(Boolean);
  if (brands.length === 0) {
    return row(c, "unknown", has, "OEM authorization required, but the tender doesn't say for which make; check manually");
  }
  const held = mafs.filter((m) => brands.some((b) => sameName(b, m.brand)));
  if (held.some((m) => stillValid(m.validUntil, today))) {
    const ok = held.find((m) => stillValid(m.validUntil, today));
    return row(c, "pass", has, "Firm holds a valid " + ok.brand + " authorization");
  }
  if (held.length) {
    return row(c, "fail", has, held[0].brand + " authorization expired on " + held[0].validUntil);
  }
  return row(c, "fail", has, "Needs authorization from " + brands.join(" / ") + "; firm holds " + has);
}

function checkCertificate(c, firm, today) {
  const v = c.values || {};
  const name = v.name || c.requirement;
  if (!name) return row(c, "unknown", "—", "Certificate name could not be read from the tender");
  const cert = (firm.certificates || []).find((x) => sameName(x.name, name));
  if (!cert) return row(c, "fail", "Not held", "Firm does not hold " + name);
  const has = cert.name + (cert.validUntil ? " (valid until " + cert.validUntil + ")" : "");
  if (!stillValid(cert.validUntil, today)) return row(c, "fail", has, cert.name + " expired on " + cert.validUntil);
  return row(c, "pass", has, "Firm holds a valid " + cert.name);
}

// Approved-makes lists name the brands allowed per item group. The firm must be able to
// supply at least one allowed brand in every group (from a MAF it holds).
function checkApprovedMakes(c, firm, today) {
  const v = c.values || {};
  const groups = Array.isArray(v.items) ? v.items.filter((g) => Array.isArray(g.brands) && g.brands.length) : [];
  const brands = (firm.oemAuthorizations || []).filter((m) => stillValid(m.validUntil, today)).map((m) => m.brand);
  const has = brands.join(", ") || "None";
  if (groups.length === 0) return row(c, "unknown", has, "Approved-makes list could not be read from the tender");
  const missing = groups.filter((g) => !g.brands.some((b) => brands.some((f) => sameName(b, f))));
  if (missing.length === 0) return row(c, "pass", has, "Firm can supply an approved make for every item group");
  return row(c, "fail", has, "No approved make held for: " + missing.map((g) => g.itemGroup + " (" + g.brands.join("/") + ")").join("; "));
}

function evaluateClause(c, firm, today, exemptions) {
  switch (c.type) {
    case "turnover": return checkTurnover(c, firm, exemptions.experienceAndTurnover);
    case "experience": return checkExperience(c, firm, exemptions.experienceAndTurnover);
    case "emd": return checkEmd(c, firm, exemptions.emd);
    case "oem_authorization": return checkOem(c, firm, today);
    case "certificate": return checkCertificate(c, firm, today);
    case "approved_makes": return checkApprovedMakes(c, firm, today);
    case "mse_exemption": {
      const v = c.values || {};
      const parts = [];
      if (v.experienceAndTurnover != null) parts.push("experience & turnover: " + (v.experienceAndTurnover ? "yes" : "no"));
      if (v.emd != null) parts.push("EMD: " + (v.emd ? "yes" : "no"));
      return row(c, "info", firm.isMSE ? "Registered MSE" : "Not an MSE", "MSE exemption in this tender: " + (parts.join(", ") || "not stated"));
    }
    default: return null;
  }
}

// clauses: AI-extracted clauses after verifyQuotes (each has `verified`, `verifyNote`).
// today: "YYYY-MM-DD". Returns one row per clause, plus an "unknown" row for each core
// clause type the tender seemed not to have.
function evaluateEligibility(clauses, firm, today) {
  const list = clauses || [];
  const exemptions = mseExemptions(list);
  const rows = [];
  for (const c of list) {
    if (!c.verified) {
      rows.push(row(c, "unknown", null, (c.verifyNote || "Quote could not be verified") + "; check the tender manually"));
      continue;
    }
    const r = evaluateClause(c, firm, today, exemptions);
    if (r) rows.push(r);
  }
  for (const type of CORE_CLAUSES) {
    if (!list.some((c) => c.type === type)) {
      rows.push(row({ type: type }, "unknown", null, "Not found in the tender; check manually"));
    }
  }
  const order = { fail: 0, unknown: 1, pass: 2, info: 3 };
  return rows.sort((a, b) => order[a.result] - order[b.result]);
}


// Double-checks each BOQ line and the SKU the AI matched to it, using plain rules.
// Red flag = very likely wrong; amber flag = the owner should look. Nothing is hidden:
// every BOQ line comes back, with its flags.

function num(x) {
  return typeof x === "number" && isFinite(x) ? x : null;
}

// Reads current (A), breaking capacity (kA), poles, cores, size (sq mm) and voltage grade (kV)
// from free text.
function parseSpecs(text) {
  const t = " " + String(text || "").toLowerCase() + " ";
  const pick = (re) => {
    const m = t.match(re);
    return m ? parseFloat(m[1]) : null;
  };
  let poles = pick(/(\d)\s*(?:poles?|p)\b/);
  if (poles == null) {
    if (/\bsp\b/.test(t)) poles = 1;
    else if (/\bdp\b/.test(t)) poles = 2;
    else if (/\btp\b/.test(t)) poles = 3;
    else if (/\bfp\b/.test(t)) poles = 4;
  }
  return {
    amps: pick(/(\d+(?:\.\d+)?)\s*(?:amps?|a)\b/),
    ka: pick(/(\d+(?:\.\d+)?)\s*ka\b/),
    poles: poles,
    cores: pick(/(\d+(?:\.\d+)?)\s*(?:cores?|c)\b/),
    sqmm: pick(/(\d+(?:\.\d+)?)\s*(?:sq\.?\s*mm|sqmm|mm2|mm²)/),
    kv: pick(/(\d+(?:\.\d+)?)\s*kv\b/),
  };
}

function normUnit(u) {
  const s = String(u || "").toLowerCase().replace(/[^a-z]/g, "");
  if (["no", "nos", "number", "numbers", "each", "ea", "pcs", "pc", "piece", "pieces"].includes(s)) return "nos";
  if (["m", "mtr", "mtrs", "meter", "meters", "metre", "metres", "rm", "rmt"].includes(s)) return "m";
  if (["set", "sets"].includes(s)) return "set";
  return s;
}

function sameBrand(a, b) {
  const n = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  return !!n(a) && !!n(b) && (n(a).includes(n(b)) || n(b).includes(n(a)));
}

function specFlags(boqText, sku) {
  const want = parseSpecs(boqText);
  const got = parseSpecs(sku.description);
  if (num(sku.ratingKA) != null) got.ka = sku.ratingKA;
  if (num(sku.poles) != null) got.poles = sku.poles;
  const flags = [];
  const differs = (key, label, unit) => {
    if (want[key] != null && got[key] != null && want[key] !== got[key]) {
      flags.push({ level: "red", text: label + " mismatch: tender " + want[key] + unit + ", SKU " + got[key] + unit });
    }
  };
  differs("amps", "Current rating", " A");
  differs("poles", "Poles", "");
  differs("cores", "Cores", "");
  differs("sqmm", "Cable size", " sq mm");
  if (want.ka != null && got.ka != null) {
    if (got.ka < want.ka) {
      flags.push({ level: "red", text: "Breaking capacity too low: tender " + want.ka + " kA, SKU " + got.ka + " kA" });
    } else if (got.ka > want.ka) {
      flags.push({ level: "amber", text: "Higher breaking capacity than asked (" + got.ka + " vs " + want.ka + " kA); check price" });
    }
  }
  return flags;
}

const GROUP_STOP_WORDS = new Set(["and", "or", "of", "the", "all", "for", "with", "items", "item", "type"]);

function groupWords(text) {
  return String(text || "")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((w) => w && !GROUP_STOP_WORDS.has(w))
    .map((w) => (w.length > 3 && w.endsWith("s") && !w.endsWith("ss") ? w.slice(0, -1) : w));
}

// The approved-makes group a BOQ line belongs to, if any. A group name like
// "MCB / RCCB / Distribution Boards" lists alternatives; a line belongs to the group when
// every word of one alternative appears in its description ("LT panel" needs both words).
function groupForLine(description, groups) {
  const words = new Set(groupWords(description));
  return (groups || []).find((g) =>
    String(g.itemGroup || "")
      .split(/\/|,|\band\b|&(?![a-z])/i)
      .map(groupWords)
      .some((alt) => alt.length > 0 && alt.every((w) => words.has(w))),
  );
}

// boqRows: AI-extracted BOQ lines after verifyQuotes and readBoqLines. matches:
// [{ item, sku, confidence, reason }] from the AI. priceRows: validated price-list rows.
// approvedGroups: [{ itemGroup, brands }] from the tender's approved-makes list ([] if none);
// a line is only checked against the group it belongs to.
function checkMatches(boqRows, matches, priceRows, approvedGroups) {
  const skuMap = new Map((priceRows || []).map((p) => [String(p.sku).trim().toLowerCase(), p]));
  const matchMap = new Map((matches || []).map((m) => [String(m.item), m]));
  const groups = (approvedGroups || []).filter((g) => g && Array.isArray(g.brands) && g.brands.length);

  return (boqRows || []).map((r) => {
    const qty = num(r.qty);
    const rate = num(r.rate);
    const amount = num(r.amount);
    const out = {
      item: r.item,
      description: r.description,
      unit: r.unit || null,
      qty: qty,
      page: r.page == null ? null : r.page,
      quote: r.quote || null,
      printedRate: rate,
      printedAmount: amount,
      status: "ok",
      sku: null,
      skuDescription: null,
      brand: null,
      listPrice: null,
      discountPct: null,
      confidence: null,
      matchReason: null,
      flags: [],
    };

    // Is the line itself trustworthy?
    if (!r.verified) {
      out.status = "unreliable";
      out.flags.push({ level: "red", text: (r.verifyNote || "Line not found in the PDF") + "; not priced" });
    }
    if (qty == null || qty <= 0 || !r.unit) {
      out.status = "unreliable";
      out.flags.push({ level: "red", text: "Quantity or unit could not be extracted reliably; not priced" });
    }
    if (r.qtyMismatch != null) {
      out.flags.push({ level: "red", text: "AI read quantity " + qty + ", but the PDF line says " + r.qtyMismatch });
    }
    if (qty != null && rate != null && amount != null && Math.abs(qty * rate - amount) > 1) {
      out.flags.push({ level: "red", text: "Printed amount " + amount + " ≠ qty × rate (" + +(qty * rate).toFixed(2) + ")" });
    }

    // Is the SKU match trustworthy?
    const m = matchMap.get(String(r.item));
    const sku = m && m.sku ? skuMap.get(String(m.sku).trim().toLowerCase()) : null;
    if (!sku) {
      if (out.status === "ok") out.status = "unmatched";
      out.flags.push({
        level: "amber",
        text: m && m.sku ? "AI suggested SKU " + m.sku + ", which isn't in the price lists; price manually" : "No matching SKU in the price lists; price manually",
      });
      return out;
    }
    out.sku = sku.sku;
    out.skuDescription = sku.description;
    out.brand = sku.brand;
    out.listPrice = sku.listPrice;
    out.discountPct = sku.discountPct;
    out.confidence = num(m.confidence);
    out.matchReason = m.reason || null;

    if (out.confidence == null || out.confidence < 0.7) {
      out.flags.push({ level: "amber", text: "Unsure match (confidence " + (out.confidence == null ? "?" : out.confidence.toFixed(2)) + "); review" });
    }
    out.flags.push(...specFlags(r.description, sku));
    const group = groupForLine(r.description, groups);
    if (group && !group.brands.some((b) => sameBrand(b, sku.brand))) {
      out.flags.push({ level: "amber", text: sku.brand + " is not an approved make for " + group.itemGroup + " (" + group.brands.join(", ") + ")" });
    }
    if (r.unit && sku.unit && normUnit(r.unit) !== normUnit(sku.unit)) {
      out.flags.push({ level: "amber", text: "Unit differs: tender " + r.unit + ", price list " + sku.unit });
    }
    return out;
  });
}


// Prices the checked BOQ. All money is worked out in whole paise (₹1 = 100 paise) so totals
// add up exactly, then shown in rupees.
//   unit cost = list price × (1 − discount)
//   amount    = qty × unit cost
//   bid rate  = unit cost × (1 + markup)
//   margin %  = (bid total − cost total) ÷ bid total
// Only lines with status "ok" are priced; the rest stay listed with their flags.

function toPaise(rupees) {
  return Math.round(rupees * 100);
}

function toRupees(paise) {
  return paise / 100;
}

// rows: output of checkMatches. firm: { markupPct }.
function priceBoq(rows, firm) {
  const markup = typeof firm.markupPct === "number" ? firm.markupPct : 0;
  let costTotal = 0;
  let bidTotal = 0;
  let priced = 0;

  const out = (rows || []).map((r) => {
    const line = Object.assign({}, r, { unitCost: null, costAmount: null, bidRate: null, bidAmount: null });
    if (r.status !== "ok") return line;
    const unitCost = Math.round((toPaise(r.listPrice) * (100 - r.discountPct)) / 100);
    const costAmount = Math.round(unitCost * r.qty);
    const bidRate = Math.round((unitCost * (100 + markup)) / 100);
    const bidAmount = Math.round(bidRate * r.qty);
    costTotal += costAmount;
    bidTotal += bidAmount;
    priced++;
    line.unitCost = toRupees(unitCost);
    line.costAmount = toRupees(costAmount);
    line.bidRate = toRupees(bidRate);
    line.bidAmount = toRupees(bidAmount);
    return line;
  });

  const count = (fn) => out.filter(fn).length;
  return {
    rows: out,
    totals: {
      costTotal: toRupees(costTotal),
      bidTotal: toRupees(bidTotal),
      marginPct: bidTotal > 0 ? Math.round(((bidTotal - costTotal) / bidTotal) * 10000) / 100 : null,
      pricedLines: priced,
      totalLines: out.length,
      unpricedLines: out.length - priced,
      redLines: count((r) => r.flags.some((f) => f.level === "red")),
      amberLines: count((r) => r.flags.some((f) => f.level === "amber") && !r.flags.some((f) => f.level === "red")),
    },
  };
}


// Turns the eligibility results and the priced BOQ into GO / NO-GO / REVIEW NEEDED, with a
// reason sentence built from the actual blockers (no AI involved).
//   any fail, or margin below the firm's minimum      → NO-GO
//   else any unknown, red line, or unpriced line      → REVIEW NEEDED
//   else                                              → GO

function pageRef(r) {
  return r.page != null ? " (p. " + r.page + ")" : "";
}

function rupees(n) {
  return "₹" + Number(n).toLocaleString("en-IN", { maximumFractionDigits: 2 });
}

// eligibility: rows from evaluateEligibility. boq: { rows, totals } from priceBoq.
// firm: { minMarginPct }.
function decide(eligibility, boq, firm) {
  const rows = eligibility || [];
  const totals = (boq && boq.totals) || { pricedLines: 0, totalLines: 0, unpricedLines: 0, redLines: 0, amberLines: 0, marginPct: null };
  const fails = rows.filter((r) => r.result === "fail");
  const unknowns = rows.filter((r) => r.result === "unknown");
  const lowMargin = totals.marginPct != null && typeof firm.minMarginPct === "number" && totals.marginPct < firm.minMarginPct;

  const counts = {
    fail: fails.length,
    unknown: unknowns.length,
    pass: rows.filter((r) => r.result === "pass").length,
    redLines: totals.redLines,
    amberLines: totals.amberLines,
    unpricedLines: totals.unpricedLines,
  };

  const blockers = [];
  for (const r of fails) blockers.push(r.label + ": " + r.reason + pageRef(r));
  if (lowMargin) blockers.push("Margin " + totals.marginPct + "% is below your minimum of " + firm.minMarginPct + "%");
  if (blockers.length) {
    return { decision: "NO-GO", reason: "NO-GO. " + blockers.join("; ") + ".", blockers: blockers, counts: counts };
  }

  const reviews = [];
  for (const r of unknowns) reviews.push(r.label + ": " + r.reason + pageRef(r));
  if (totals.totalLines === 0) reviews.push("No BOQ lines were found");
  if (totals.redLines) reviews.push(totals.redLines + " BOQ line(s) flagged red");
  if (totals.unpricedLines) reviews.push(totals.unpricedLines + " BOQ line(s) could not be priced");
  if (reviews.length) {
    return { decision: "REVIEW NEEDED", reason: "Review needed before deciding. " + reviews.join("; ") + ".", blockers: reviews, counts: counts };
  }

  return {
    decision: "GO",
    reason: "GO. All " + counts.pass + " eligibility checks passed; " + totals.pricedLines + " BOQ lines priced at " +
      rupees(totals.bidTotal) + " with " + totals.marginPct + "% margin" +
      (totals.amberLines ? " (" + totals.amberLines + " line(s) worth a second look)" : "") + ".",
    blockers: [],
    counts: counts,
  };
}


// Builds the 4 Gemini requests and reads their answers. The AI only reads the tender;
// every decision is made afterwards by plain code. Each prompt asks for exact quotes so
// verifyQuotes can prove them, and says to leave a value null rather than guess.

const GEMINI_MODEL = "gemini-3-flash-preview";
const CLASSIFY_CHARS_PER_PAGE = 1500;
const MAX_PAGES_PER_CALL = 40;

const RULES_FOR_AI =
  "Rules: answer only from the pages given. Copy every quote EXACTLY as printed (same words, same order, " +
  "max 40 words) from the page you cite. If something isn't stated, leave it null; never guess or infer.";

function pagesBlock(pages, maxChars) {
  return pages
    .map((p) => "=== PAGE " + p.page + " ===\n" + (maxChars ? p.text.slice(0, maxChars) : p.text))
    .join("\n\n");
}

function geminiRequest(prompt, input, schema) {
  return {
    model: GEMINI_MODEL,
    body: {
      contents: [{ role: "user", parts: [{ text: prompt + "\n\n" + input }] }],
      generationConfig: {
        responseMimeType: "application/json",
        responseSchema: schema,
        thinkingConfig: { thinkingLevel: "low" },
      },
    },
  };
}

const S = {
  str: { type: "STRING" },
  strOrNull: { type: "STRING", nullable: true },
  numOrNull: { type: "NUMBER", nullable: true },
  intOrNull: { type: "INTEGER", nullable: true },
  boolOrNull: { type: "BOOLEAN", nullable: true },
};

// A1: label every page, using only the start of each page to stay fast.
function classifyRequest(pages) {
  const prompt =
    "You are reading an Indian government tender (GeM / CPPP / state portal) for electrical or solar work. " +
    "Label each page: 'eligibility' if it states bidder qualification or bid conditions (EMD, turnover, past " +
    "experience, OEM/manufacturer authorization, certificates, MSE exemption, approved makes/brands); 'boq' if it " +
    "contains Bill of Quantities / schedule of items with quantities; otherwise 'other'. A page can have more " +
    "than one label. Return every page number given.";
  const schema = {
    type: "OBJECT",
    properties: {
      pages: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            page: { type: "INTEGER" },
            labels: { type: "ARRAY", items: { type: "STRING", enum: ["eligibility", "boq", "other"] } },
          },
          required: ["page", "labels"],
        },
      },
    },
    required: ["pages"],
  };
  return geminiRequest(prompt, pagesBlock(pages, CLASSIFY_CHARS_PER_PAGE), schema);
}

// Pages the AI labelled, plus pages whose text contains a keyword (a safety net in case
// the classifier missed one), in page order, capped so the call stays fast.
function pickPages(pages, classified, label, keywords) {
  const labelled = new Set(
    ((classified && classified.pages) || []).filter((p) => (p.labels || []).includes(label)).map((p) => p.page),
  );
  const picked = pages.filter((p) => labelled.has(p.page) || keywords.test(p.text));
  return picked.slice(0, MAX_PAGES_PER_CALL);
}

const ELIGIBILITY_KEYWORDS = /turnover|e\.?m\.?d|earnest money|bid security|experience|authori[sz]ation|\bmaf\b|iso\s?\d|certificat|\bmse\b|approved make|list of makes/i;
const BOQ_KEYWORDS = /bill of quantit|\bboq\b|schedule of (items|quantit|requirement)|price schedule/i;

// Every field in the AI's answer is REQUIRED (null when it doesn't apply). Gemini quietly
// drops optional fields on long inputs, which lost quantities, EMD amounts and order values.
// So each clause is one flat object with every field present; toClauses() reshapes it.
const CLAUSE_FIELDS = {
  type: { type: "STRING", enum: ["emd", "turnover", "experience", "oem_authorization", "certificate", "mse_exemption", "approved_makes"] },
  requirement: S.str,
  page: S.intOrNull,
  quote: S.strOrNull,
  makes: { type: "ARRAY", items: S.str },
  emdRequired: S.boolOrNull,
  emdAmountInr: S.numOrNull,
  minAvgAnnualTurnoverInr: S.numOrNull,
  notRequired: S.boolOrNull,
  experienceYears: S.numOrNull,
  lookbackYears: S.numOrNull,
  orderOptions: {
    type: "ARRAY",
    items: {
      type: "OBJECT",
      properties: { count: { type: "INTEGER" }, eachAtLeastInr: { type: "NUMBER" } },
      required: ["count", "eachAtLeastInr"],
    },
  },
  oemRequired: S.boolOrNull,
  certificateName: S.strOrNull,
  mseExemptExperienceTurnover: S.boolOrNull,
  mseExemptEmd: S.boolOrNull,
  itemGroups: {
    type: "ARRAY",
    items: {
      type: "OBJECT",
      properties: { itemGroup: S.str, brands: { type: "ARRAY", items: S.str } },
      required: ["itemGroup", "brands"],
    },
  },
};

// Kinds of documents a tender can ask the bidder to submit (Bid Readiness checklist).
const DOC_TYPES = [
  "oem_authorization", "turnover_evidence", "experience_evidence", "emd_or_bid_security", "gst_registration",
  "pan_card", "udyam_registration", "bis_certificate", "iso_certificate", "type_test_report", "technical_datasheet",
  "local_content_declaration", "signed_annexure", "electrical_licence", "other",
];

const DOCUMENT_FIELDS = {
  docType: { type: "STRING", enum: DOC_TYPES },
  name: S.str,
  requirement: { type: "STRING", enum: ["required", "conditional"] },
  condition: S.strOrNull,
  page: S.intOrNull,
  quote: S.strOrNull,
};

// A2: find the eligibility clauses with normalized values, page and exact quote, and the
// documents the bidder must submit.
function eligibilityRequest(pages, classified) {
  const prompt =
    "Extract the bidder eligibility clauses from these tender pages. Clause types and the fields to fill:\n" +
    "- emd: earnest money / bid security. emdRequired (false only if the tender says no EMD), emdAmountInr.\n" +
    "- turnover: minimum average annual turnover. minAvgAnnualTurnoverInr in rupees (1 lakh = 100000, 1 crore = 10000000). notRequired=true only if the tender explicitly says none.\n" +
    "- experience: experienceYears = minimum years the bidder must have been doing similar work. orderOptions = every " +
    "'N similar works/orders each of at least ₹X' option, e.g. [{count:3, eachAtLeastInr:2000000}, {count:1, eachAtLeastInr:4000000}]. " +
    "lookbackYears = the period in which those works must have been completed ('during the last 7 years' → 7). " +
    "A look-back period is NOT experienceYears: leave experienceYears null unless the tender asks for N years of experience.\n" +
    "- oem_authorization: manufacturer/OEM authorization (MAF). oemRequired.\n" +
    "- certificate: one clause per required certificate/licence (ISO, BIS, electrical licence…). certificateName.\n" +
    "- mse_exemption: whether MSEs are exempted. mseExemptExperienceTurnover and mseExemptEmd as true/false, null if not stated.\n" +
    "- approved_makes: itemGroups = one object per item group: itemGroup = the item name only (e.g. \"MCCB\"), brands = each brand as a separate string.\n" +
    "Every field must be present: use null (or [] for lists) when it doesn't apply to the clause type. Return exactly " +
    "one clause each for emd, turnover, experience and oem_authorization (if present); certificate, mse_exemption and " +
    "approved_makes may repeat. makes = every manufacturer/brand name in the quote ([] if none).\n" +
    "Also list in documents[] every document the tender explicitly asks the bidder to submit or upload (MAF/OEM " +
    "authorization, turnover or CA certificate, experience proof such as purchase orders or completion certificates, " +
    "EMD or bid security declaration, GST, PAN, Udyam, BIS or ISO certificates, type-test reports, datasheets, local " +
    "content declaration, signed annexures/undertakings/forms, electrical licence…). requirement = 'conditional' when " +
    "the tender says it applies only in some cases (condition = that case, e.g. 'if the bidder is not the OEM'); " +
    "otherwise 'required'. Only list documents the tender actually asks for; never assume a standard list. " +
    RULES_FOR_AI;
  const schema = {
    type: "OBJECT",
    properties: {
      clauses: { type: "ARRAY", items: { type: "OBJECT", properties: CLAUSE_FIELDS, required: Object.keys(CLAUSE_FIELDS) } },
      documents: { type: "ARRAY", items: { type: "OBJECT", properties: DOCUMENT_FIELDS, required: Object.keys(DOCUMENT_FIELDS) } },
    },
    required: ["clauses", "documents"],
  };
  return geminiRequest(prompt, pagesBlock(pickPages(pages, classified, "eligibility", ELIGIBILITY_KEYWORDS)), schema);
}

// Reshapes A2's flat answer into the { type, requirement, values, makes, page, quote } clauses
// the rules read. Clauses already in that shape (e.g. the demo's) pass through unchanged.
function toClauses(answer) {
  return ((answer && answer.clauses) || []).map((c) => {
    if (c.values) return c;
    const values = {
      required: c.type === "emd" ? c.emdRequired : c.type === "oem_authorization" ? c.oemRequired : null,
      amountInr: c.emdAmountInr,
      minAvgAnnualInr: c.minAvgAnnualTurnoverInr,
      notRequired: c.notRequired,
      years: c.experienceYears,
      lookbackYears: c.lookbackYears,
      orderOptions: c.orderOptions,
      name: c.certificateName,
      experienceAndTurnover: c.mseExemptExperienceTurnover,
      emd: c.mseExemptEmd,
      items: c.itemGroups,
    };
    return { type: c.type, requirement: c.requirement, values: values, makes: c.makes || [], page: c.page, quote: c.quote };
  });
}

// A3: pull out the BOQ lines.
function boqRequest(pages, classified) {
  const prompt =
    "Extract every line item of the Bill of Quantities (BOQ / schedule of items) from these tender pages. " +
    "For each line: item number as printed, full description (join wrapped lines), unit, quantity (qty), and the " +
    "rate and amount if printed (null if not). Every field must be present. page = where the line starts; quote = " +
    "the exact printed text of the line's first few words of description (max 15 words). Skip headings and totals. " +
    RULES_FOR_AI;
  const schema = {
    type: "OBJECT",
    properties: {
      rows: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            item: S.str,
            description: S.str,
            unit: S.strOrNull,
            qty: S.numOrNull,
            rate: S.numOrNull,
            amount: S.numOrNull,
            page: S.intOrNull,
            quote: S.strOrNull,
          },
          required: ["item", "description", "unit", "qty", "rate", "amount", "page", "quote"],
        },
      },
    },
    required: ["rows"],
  };
  return geminiRequest(prompt, pagesBlock(pickPages(pages, classified, "boq", BOQ_KEYWORDS)), schema);
}

// A4: choose a SKU for each BOQ line, only from that line's shortlist.
function matchRequest(boqRows, shortlist) {
  const byItem = new Map(shortlist.map((s) => [String(s.item), s.candidates]));
  const lines = boqRows
    .filter((r) => (byItem.get(String(r.item)) || []).length > 0)
    .map((r) => ({
      item: r.item,
      description: r.description,
      unit: r.unit,
      candidates: byItem.get(String(r.item)).map((c) => ({ sku: c.sku, description: c.description, brand: c.brand, unit: c.unit })),
    }));
  const prompt =
    "Match each tender BOQ line to the supplier SKU that is the same product. Choose ONLY from that line's " +
    "candidates. Ratings must match exactly (amps, poles, kA, cores, sq mm, watts). If no candidate is the same " +
    "product, return sku null. confidence: 0 to 1, how sure you are it's the same product. reason: one short line.";
  const schema = {
    type: "OBJECT",
    properties: {
      matches: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: { item: S.str, sku: S.strOrNull, confidence: { type: "NUMBER" }, reason: S.str },
          required: ["item", "sku", "confidence", "reason"],
        },
      },
    },
    required: ["matches"],
  };
  return { lineCount: lines.length, request: geminiRequest(prompt, JSON.stringify(lines), schema) };
}

// Document requirements from A2, checked into a fixed shape: unknown types become "other",
// anything without a name is dropped. (The AI's output is never trusted as-is.)
function toDocRequirements(answer) {
  return ((answer && answer.documents) || [])
    .filter((d) => d && typeof d.name === "string" && d.name.trim())
    .map((d) => ({
      docType: DOC_TYPES.includes(d.docType) ? d.docType : "other",
      name: d.name.trim().slice(0, 120),
      requirement: d.requirement === "conditional" ? "conditional" : "required",
      condition: typeof d.condition === "string" && d.condition.trim() ? d.condition.trim().slice(0, 200) : null,
      page: Number.isInteger(d.page) ? d.page : null,
      quote: typeof d.quote === "string" && d.quote.trim() ? d.quote : null,
    }));
}

// Fields read from a supporting document (MAF letter, certificate, purchase order…).
const SUPPORT_FIELDS = ["issuer", "holder", "manufacturer", "productCategories", "tenderReference", "territory", "issueDate", "validUntil", "signatory", "certificateNumber", "standard"];

// A6: read the bidder's supporting documents (only those with readable text). docs:
// [{ name, pages: [{page, text}] }]. Each field needs an exact quote so code can check it.
function supportingDocsRequest(docs) {
  const input = docs
    .map((d, i) => `##### DOCUMENT ${i + 1}: ${d.name}\n` + d.pages.map((p) => `=== PAGE ${p.page} ===\n${p.text.slice(0, 6000)}`).join("\n\n"))
    .join("\n\n");
  const prompt =
    "These are documents a bidder plans to submit with an Indian government tender. For each DOCUMENT n, give " +
    "docIndex = n, docType (what it is; 'other' if none fit), title, and these fields when the document states them " +
    "(null when it doesn't): issuer (who issued it), holder (who it is issued to / the authorized dealer or bidder), " +
    "manufacturer (the OEM, for authorization letters), productCategories (products or product families covered), " +
    "tenderReference (bid/tender number it is specific to), territory, issueDate and validUntil (as YYYY-MM-DD), " +
    "signatory (name and designation of who signed), certificateNumber, standard (e.g. ISO 9001:2015, IS 694). " +
    "For every non-null field add one evidence entry {field, page, quote} with the exact words from that document " +
    "that state it. Never infer a date, name or scope that isn't written. " +
    RULES_FOR_AI;
  const schema = {
    type: "OBJECT",
    properties: {
      documents: {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            docIndex: { type: "INTEGER" },
            docType: { type: "STRING", enum: DOC_TYPES },
            title: S.strOrNull,
            issuer: S.strOrNull,
            holder: S.strOrNull,
            manufacturer: S.strOrNull,
            productCategories: { type: "ARRAY", items: S.str },
            tenderReference: S.strOrNull,
            territory: S.strOrNull,
            issueDate: S.strOrNull,
            validUntil: S.strOrNull,
            signatory: S.strOrNull,
            certificateNumber: S.strOrNull,
            standard: S.strOrNull,
            evidence: {
              type: "ARRAY",
              items: { type: "OBJECT", properties: { field: { type: "STRING", enum: SUPPORT_FIELDS }, page: S.intOrNull, quote: S.strOrNull }, required: ["field", "page", "quote"] },
            },
          },
          required: ["docIndex", "docType", "title", ...SUPPORT_FIELDS, "evidence"],
        },
      },
    },
    required: ["documents"],
  };
  return geminiRequest(prompt, input, schema);
}

// A6's answer checked into a fixed shape, keyed to the uploaded files by docIndex.
function toSupportingDocs(answer, docCount) {
  const str = (v) => (typeof v === "string" && v.trim() ? v.trim().slice(0, 300) : null);
  const date = (v) => (typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v.trim()) ? v.trim() : null);
  return ((answer && answer.documents) || [])
    .filter((d) => d && Number.isInteger(d.docIndex) && d.docIndex >= 1 && d.docIndex <= docCount)
    .map((d) => ({
      docIndex: d.docIndex,
      docType: DOC_TYPES.includes(d.docType) ? d.docType : "other",
      title: str(d.title),
      issuer: str(d.issuer),
      holder: str(d.holder),
      manufacturer: str(d.manufacturer),
      productCategories: Array.isArray(d.productCategories) ? d.productCategories.map(str).filter(Boolean).slice(0, 20) : [],
      tenderReference: str(d.tenderReference),
      territory: str(d.territory),
      issueDate: date(d.issueDate),
      validUntil: date(d.validUntil),
      signatory: str(d.signatory),
      certificateNumber: str(d.certificateNumber),
      standard: str(d.standard),
      evidence: (Array.isArray(d.evidence) ? d.evidence : [])
        .filter((e) => e && SUPPORT_FIELDS.includes(e.field) && Number.isInteger(e.page) && typeof e.quote === "string")
        .map((e) => ({ field: e.field, page: e.page, quote: e.quote })),
    }));
}

// Reads the JSON answer out of a Gemini response; throws a readable error if there isn't one.
function readGeminiJson(response, step) {
  const cand = response && response.candidates && response.candidates[0];
  const text = cand && cand.content && (cand.content.parts || []).map((p) => p.text || "").join("");
  if (!text) {
    const why = (cand && cand.finishReason) || (response && response.promptFeedback && response.promptFeedback.blockReason) || "empty answer";
    throw new Error(step + ": the AI gave no answer (" + why + ")");
  }
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error(step + ": the AI's answer was not valid JSON");
  }
}


// Bid Readiness: what documents, technical checks and actions remain before a bid is ready for
// a human to review. Every status here is decided by plain rules from verified evidence: the AI
// only read the tender and the supporting documents. Unknown is never treated as a pass.
// Uses verifyQuote (verifyQuotes.js) and parseSpecs (matchChecks.js); the n8n "Decide" node
// stacks those files before this one.

const DOC_LABELS = {
  oem_authorization: "OEM authorization (MAF)",
  turnover_evidence: "Turnover evidence",
  experience_evidence: "Similar-work experience proof",
  emd_or_bid_security: "EMD / bid security",
  gst_registration: "GST registration",
  pan_card: "PAN",
  udyam_registration: "Udyam (MSE) registration",
  bis_certificate: "BIS certificate",
  iso_certificate: "ISO certificate",
  type_test_report: "Type-test report",
  technical_datasheet: "Technical datasheet",
  local_content_declaration: "Local-content declaration",
  signed_annexure: "Signed annexure / undertaking",
  electrical_licence: "Electrical contractor licence",
  other: "Other document",
};

// Which firm-profile certificate can stand for a document type (only as "you say you hold it").
const PROFILE_CERT_HINTS = {
  gst_registration: /gst/i,
  udyam_registration: /udyam|msme/i,
  iso_certificate: /iso/i,
  bis_certificate: /\bbis\b/i,
  electrical_licence: /electric.*licen/i,
};

function rdNorm(s) {
  return String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

const RD_COMPANY_WORDS = /\b(pvt|private|ltd|limited|india|co|company|llp|inc|m\/s|ms|electric(al)?s?)\b\.?/gi;

// Two names refer to the same firm or brand: "SCHNEIDER ELECTRIC INDIA PVT LTD" ~ "Schneider",
// and an abbreviation ~ the full name: "L&T" ~ "Larsen & Toubro Limited".
function rdSameName(a, b) {
  const strip = (s) => rdNorm(String(s || "").replace(RD_COMPANY_WORDS, ""));
  const x = strip(a);
  const y = strip(b);
  if (!x || !y) return false;
  if (x.includes(y) || y.includes(x)) return true;
  const initials = (s) => (String(s || "").replace(RD_COMPANY_WORDS, "").match(/[A-Za-z][A-Za-z]+/g) || []).map((w) => w[0].toLowerCase()).join("");
  const isShort = (s) => s.length >= 2 && s.length <= 4;
  return (isShort(x) && initials(b) === x) || (isShort(y) && initials(a) === y);
}

// Lowercase words without a plural "s", for comparing product names ("MCCBs" ~ "MCCB").
function rdWords(s) {
  return (String(s || "").toLowerCase().match(/[a-z]{3,}/g) || []).map((w) => (w.length > 3 && w.endsWith("s") ? w.slice(0, -1) : w));
}

// "31/03/2027", "31-Mar-2027", "March 31, 2027" in a quote all contain 2027, 31 and 3 or Mar.
function rdDateInQuote(iso, quote) {
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return false;
  const q = String(quote || "").toLowerCase();
  const months = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
  const day = String(Number(m[3]));
  const mon = Number(m[2]);
  const hasYear = q.includes(m[1]) || q.includes("'" + m[1].slice(2)) || new RegExp("[/.-]" + m[1].slice(2) + "\\b").test(q);
  const hasDay = new RegExp("(^|\\D)0?" + day + "(\\D|$)").test(q);
  const hasMonth = q.includes(months[mon - 1]) || new RegExp("(^|\\D)0?" + mon + "(\\D|$)").test(q);
  return hasYear && hasDay && hasMonth;
}

// A field from a supporting document counts only if its quote is really on the cited page of
// that document AND the quote actually contains the value.
function rdFieldVerified(doc, field, value) {
  if (value == null || (Array.isArray(value) && value.length === 0)) return false;
  const evidence = (doc.evidence || []).filter((e) => e.field === field);
  return evidence.some((e) => {
    if (!verifyQuote(doc.pages, e.page, e.quote).verified) return false;
    if (field === "issueDate" || field === "validUntil") return rdDateInQuote(value, e.quote);
    const values = Array.isArray(value) ? value : [value];
    return values.some((v) => {
      const words = String(v).toLowerCase().match(/[a-z0-9]+/g) || [];
      const q = String(e.quote).toLowerCase();
      return words.length > 0 && words.every((w) => q.includes(w));
    });
  });
}

// Joins the uploaded files with what the AI read from them. files: [{name, pages, unreadable,
// error}]; aiDocs: toSupportingDocs(...) output. Unverified fields are set to null.
function checkSupportingDocs(files, aiDocs) {
  return (files || []).map((f, i) => {
    const base = { index: i + 1, fileName: f.name, readable: !f.unreadable, problem: f.error || null, docType: null, title: null, fields: {}, unverifiedFields: [] };
    if (f.unreadable) return Object.assign(base, { problem: f.error || "No readable text (scanned?). Not analysed." });
    const ai = (aiDocs || []).find((d) => d.docIndex === i + 1);
    if (!ai) return Object.assign(base, { problem: "The AI couldn't identify this document." });
    const withPages = Object.assign({}, ai, { pages: f.pages });
    const fields = {};
    const unverified = [];
    for (const k of SUPPORT_FIELD_NAMES) {
      const v = ai[k];
      if (v == null || (Array.isArray(v) && !v.length)) continue;
      if (rdFieldVerified(withPages, k, v)) fields[k] = v;
      else unverified.push(k);
    }
    return Object.assign(base, { docType: ai.docType, title: ai.title, fields: fields, unverifiedFields: unverified });
  });
}
const SUPPORT_FIELD_NAMES = ["issuer", "holder", "manufacturer", "productCategories", "tenderReference", "territory", "issueDate", "validUntil", "signatory", "certificateNumber", "standard"];

// The tender's own reference, read by code from the page text (GeM bid number or NIT number).
function tenderReference(pages) {
  for (const p of pages || []) {
    const gem = String(p.text).match(/GEM\/\d{4}\/[BR]\/\d+/);
    if (gem) return gem[0];
  }
  for (const p of pages || []) {
    const nit = String(p.text).match(/NIT\s*No\.?\s*[:\-]?\s*([A-Za-z0-9][A-Za-z0-9\/\-.]{3,40})/i);
    if (nit) return nit[1].replace(/[.,]$/, "");
  }
  return null;
}

// OEM authorization: compares the tender's requirement with the uploaded letter(s) field by field.
// Returns { status: not_required | missing | verified | needs_review | conflict, fields, ... }.
function checkOemAuthorization(opts) {
  const { clauses, docRequirements, supportingDocs, firm, today, tenderRef, boqDescriptions } = opts;
  const clause = (clauses || []).find((c) => c.type === "oem_authorization");
  const docReq = (docRequirements || []).find((d) => d.docType === "oem_authorization");
  const source = clause && clause.verified ? clause : docReq && docReq.verified ? docReq : clause || docReq || null;
  const requiredByTender =
    (clause && clause.verified && clause.values && clause.values.required === true) ||
    (docReq && docReq.verified && docReq.requirement === "required");
  const conditional = !requiredByTender && docReq && docReq.verified && docReq.requirement === "conditional";
  const unverifiedMention = !requiredByTender && !conditional && ((clause && !clause.verified) || (docReq && !docReq.verified));
  const tenderMakes = (clause && clause.verified ? (clause.values && clause.values.brands && clause.values.brands.length ? clause.values.brands : clause.makes) : []) || [];
  const letters = (supportingDocs || []).filter((d) => d.docType === "oem_authorization");
  const base = {
    requirement: requiredByTender ? "required" : conditional ? "conditional" : unverifiedMention ? "not established" : "not required",
    condition: conditional ? docReq.condition : null,
    tenderMakes: tenderMakes,
    page: source ? source.page : null,
    quote: source ? source.quote : null,
    letterFile: null,
    fields: [],
  };

  if (!requiredByTender && !conditional && !unverifiedMention && letters.length === 0) {
    return Object.assign(base, { status: "not_required", reason: "The tender doesn't ask for an OEM authorization (none found with a verified quote)." });
  }
  if (letters.length === 0) {
    if (unverifiedMention) {
      return Object.assign(base, { status: "needs_review", reason: "The tender seems to mention OEM authorization, but the quote couldn't be verified. Check the tender." });
    }
    return Object.assign(base, {
      status: requiredByTender ? "missing" : "needs_review",
      reason: requiredByTender
        ? "The tender requires an OEM authorization and none was uploaded."
        : "The tender asks for an OEM authorization only " + (docReq.condition || "in some cases") + ". Check whether it applies to you.",
    });
  }

  // Pick the letter that best matches the tender's makes.
  const letter = letters.find((l) => tenderMakes.some((m) => rdSameName(m, l.fields.manufacturer))) || letters[0];
  const f = letter.fields;
  const row = (field, tender, letterValue, result, note) => ({ field: field, tender: tender, letter: letterValue, result: result, note: note || null });
  const fields = [];

  // Manufacturer
  if (!f.manufacturer) fields.push(row("Manufacturer / OEM", tenderMakes.join(" / ") || "Not specified", null, "missing", "Not stated (or not verifiable) in the letter"));
  else if (!tenderMakes.length) fields.push(row("Manufacturer / OEM", "Not specified", f.manufacturer, "match", "Tender names no specific make"));
  else if (tenderMakes.some((m) => rdSameName(m, f.manufacturer))) fields.push(row("Manufacturer / OEM", tenderMakes.join(" / "), f.manufacturer, "match"));
  else fields.push(row("Manufacturer / OEM", tenderMakes.join(" / "), f.manufacturer, "conflict", "Letter is from a make the tender doesn't ask for"));

  // Authorized party
  if (!f.holder) fields.push(row("Authorized bidder", firm.name, null, "missing", "Letter doesn't name who is authorized"));
  else if (rdSameName(f.holder, firm.name)) fields.push(row("Authorized bidder", firm.name, f.holder, "match"));
  else fields.push(row("Authorized bidder", firm.name, f.holder, "conflict", "Letter authorizes someone else"));

  // Product scope
  const cats = f.productCategories || [];
  if (!cats.length) fields.push(row("Product family", "Tendered items", null, "missing", "Letter doesn't state which products it covers"));
  else {
    const words = cats.flatMap(rdWords);
    const covers = (boqDescriptions || []).some((d) => {
      const have = rdWords(d);
      return words.some((w) => have.includes(w));
    });
    fields.push(row("Product family", "Tendered items", cats.join(", "), covers ? "match" : "review", covers ? null : "Couldn't confirm the letter covers the tendered items"));
  }

  // Tender reference
  const bidSpecific = /specific to (this|the) (bid|tender)|bid specific|tender specific|for this (bid|tender)/i.test(String(base.quote || ""));
  if (!f.tenderReference) fields.push(row("Tender reference", tenderRef || "—", null, bidSpecific ? "missing" : "info", bidSpecific ? "Tender asks for a bid-specific letter" : "Not stated"));
  else if (tenderRef && rdNorm(f.tenderReference).includes(rdNorm(tenderRef))) fields.push(row("Tender reference", tenderRef, f.tenderReference, "match"));
  else if (tenderRef) fields.push(row("Tender reference", tenderRef, f.tenderReference, "conflict", "Letter is for a different bid"));
  else fields.push(row("Tender reference", "—", f.tenderReference, "review", "Couldn't read this tender's reference to compare"));

  // Territory, dates, signatory
  fields.push(row("Territory", "—", f.territory || null, f.territory ? "info" : "info", f.territory ? null : "Not stated"));
  if (!f.issueDate) fields.push(row("Issue date", "—", null, "missing", "No verifiable issue date"));
  else if (f.issueDate > today) fields.push(row("Issue date", "—", f.issueDate, "review", "Dated in the future: check the date"));
  else fields.push(row("Issue date", "—", f.issueDate, "info"));
  if (!f.validUntil) fields.push(row("Valid until", "On the bid date", null, "missing", "No verifiable validity date"));
  else if (f.validUntil < today) fields.push(row("Valid until", "On the bid date", f.validUntil, "conflict", "Expired"));
  else fields.push(row("Valid until", "On the bid date", f.validUntil, "match"));
  fields.push(row("Authorized signatory", "—", f.signatory || null, f.signatory ? "match" : "missing", f.signatory ? null : "Signatory not stated"));

  const conflict = fields.find((x) => x.result === "conflict");
  const keyMissing = fields.find((x) => (x.result === "missing" || x.result === "review") && x.field !== "Territory");
  let status;
  let reason;
  if (conflict) {
    status = "conflict";
    reason = conflict.field + ": " + (conflict.note || "doesn't match the tender") + (conflict.letter ? " (" + conflict.letter + ")" : "");
  } else if (keyMissing || letter.unverifiedFields.length) {
    status = "needs_review";
    reason = keyMissing ? keyMissing.field + ": " + (keyMissing.note || "can't be verified") : "Some fields in the letter couldn't be matched to its text";
  } else {
    status = "verified";
    reason = "Letter matches the tender on manufacturer, bidder, products, reference and validity.";
  }
  return Object.assign(base, { status: status, reason: reason, letterFile: letter.fileName, fields: fields, unverifiedFields: letter.unverifiedFields });
}

function rdAction(status, label, extra) {
  if (status === "Missing") return "Get and upload the " + label + extra;
  if (status === "Expired") return "Renew the " + label + " before the bid closes" + extra;
  if (status === "Needs review") return "Check the " + label + extra;
  return null;
}

// The document checklist: one row per document the tender asks for.
function evaluateDocuments(opts) {
  const { docRequirements, supportingDocs, firm, today, oem } = opts;
  return (docRequirements || []).map((req) => {
    const label = req.name || DOC_LABELS[req.docType] || "Document";
    const out = {
      docType: req.docType,
      name: label,
      requirement: !req.verified ? "not established" : req.requirement,
      condition: req.condition || null,
      page: req.page,
      quote: req.quote,
      status: "Needs review",
      reason: "",
      action: null,
      evidence: null,
    };
    const set = (status, reason, action) => Object.assign(out, { status: status, reason: reason, action: action === undefined ? rdAction(status, label, "") : action });

    if (!req.verified) return set("Needs review", (req.verifyNote || "Requirement quote not found in the tender") + ". Check the tender.", "Find this requirement in the tender and confirm it");

    if (req.docType === "oem_authorization" && oem) {
      out.evidence = oem.letterFile;
      if (oem.status === "verified") return set("Verified", oem.reason, null);
      if (oem.status === "conflict") return set("Missing", "Uploaded letter doesn't satisfy the tender: " + oem.reason, "Get a correct MAF from " + (oem.tenderMakes.join(" / ") || "the OEM") + " naming your firm and this bid");
      if (oem.status === "missing") return set(req.requirement === "conditional" ? "Needs review" : "Missing", oem.reason, "Request a MAF from " + (oem.tenderMakes.join(" / ") || "the OEM") + " for this bid and upload it");
      return set("Needs review", oem.reason);
    }

    // Same kind of document; when the requirement names a standard number (ISO 14001, IS 694),
    // the document must state that number too.
    const sameKind = (supportingDocs || []).filter((d) => d.readable && d.docType === req.docType);
    const reqNumber = (String(req.name).match(/\b\d{3,5}\b/) || [])[0];
    const doc = reqNumber
      ? sameKind.find((d) => String((d.fields.standard || "") + " " + (d.title || "")).includes(reqNumber))
      : sameKind[0];
    const unreadable = (supportingDocs || []).find((d) => !d.readable);

    if (doc) {
      out.evidence = doc.fileName;
      const f = doc.fields;
      if (f.validUntil && f.validUntil < today) return set("Expired", doc.fileName + " expired on " + f.validUntil + ".");
      if (f.holder && firm.name && !rdSameName(f.holder, firm.name)) return set("Needs review", doc.fileName + " is issued to \"" + f.holder + "\", not " + firm.name + ".", "Check the document is in your firm's name");
      const keyFields = ["holder", "certificateNumber", "standard", "issuer"].filter((k) => f[k]);
      if (!keyFields.length) return set("Needs review", doc.fileName + " was found, but its holder, number or issuer couldn't be verified from its text.", "Open " + doc.fileName + " and confirm it is the right document");
      if (req.requirement === "conditional") return set("Needs review", "Document uploaded; the tender asks for it only " + (req.condition || "in some cases") + ".", "Confirm whether the condition applies");
      return set("Verified", doc.fileName + ": " + keyFields.map((k) => k + " " + (Array.isArray(f[k]) ? f[k].join(", ") : f[k])).join("; ") + (f.validUntil ? "; valid until " + f.validUntil : "") + ".", null);
    }

    // Nothing uploaded: the firm profile can only say you hold it, not prove it.
    const hint = PROFILE_CERT_HINTS[req.docType];
    const profileCert = hint ? (firm.certificates || []).find((c) => hint.test(c.name) && (req.docType !== "iso_certificate" || rdNorm(req.name).includes(rdNorm(c.name).slice(0, 7)))) : null;
    if (profileCert && profileCert.validUntil && profileCert.validUntil < today) {
      return set("Expired", "Firm profile: " + profileCert.name + " expired on " + profileCert.validUntil + ".");
    }
    if (req.requirement === "conditional") {
      return set("Needs review", "Required only " + (req.condition || "in some cases") + ". Nothing uploaded.", "Check whether this applies to you; if so, upload it");
    }
    if (profileCert) {
      return set("Needs review", "Firm profile says you hold " + profileCert.name + (profileCert.validUntil ? " (valid until " + profileCert.validUntil + ")" : "") + ", but no copy was uploaded to check.", "Upload a copy of " + profileCert.name);
    }
    return set("Missing", "No uploaded document matches." + (unreadable ? " (" + unreadable.fileName + " couldn't be read.)" : ""));
  });
}

// Technical compliance matrix: one row per BOQ line, one cell per parameter the tender states.
const CRITICAL_PARAMS = { amps: "Rated current", poles: "Poles", ka: "Breaking capacity", cores: "Cores", sqmm: "Conductor size", kv: "Voltage grade" };
const PARAM_UNITS = { amps: " A", poles: "P", ka: " kA", cores: "C", sqmm: " sq mm", kv: " kV" };

function technicalCompliance(checkedRows, priceRows) {
  const bySku = new Map((priceRows || []).map((p) => [String(p.sku).toLowerCase(), p]));
  return (checkedRows || []).map((r) => {
    const want = parseSpecs(r.description);
    const sku = r.sku ? bySku.get(String(r.sku).toLowerCase()) : null;
    const got = sku ? parseSpecs(sku.description) : {};
    if (sku && typeof sku.ratingKA === "number") got.ka = sku.ratingKA;
    if (sku && typeof sku.poles === "number") got.poles = sku.poles;
    const params = [];
    for (const key of Object.keys(CRITICAL_PARAMS)) {
      if (want[key] == null) continue;
      const required = want[key] + PARAM_UNITS[key];
      const productValue = got[key] == null ? null : got[key] + PARAM_UNITS[key];
      let result;
      let note = null;
      if (!sku) {
        result = "unknown";
        note = "No matched product";
      } else if (got[key] == null) {
        result = "unknown";
        note = "Not in the catalogue entry: check the datasheet";
      } else if (key === "ka" && got.ka > want.ka) {
        result = "match";
        note = "Higher than required";
      } else if (got[key] === want[key]) result = "match";
      else {
        result = "mismatch";
        note = key === "ka" && got.ka < want.ka ? "Below the required breaking capacity" : "Doesn't match the tender";
      }
      params.push({ parameter: CRITICAL_PARAMS[key], required: required, product: productValue, result: result, note: note });
    }
    const brandFlag = (r.flags || []).find((f) => /approved make/.test(f.text));
    if (sku) {
      params.unshift({ parameter: "Make", required: brandFlag ? brandFlag.text.replace(/^.*\(([^)]*)\)$/, "$1") : "Any / not restricted", product: sku.brand, result: brandFlag ? "mismatch" : "match", note: brandFlag ? "Not an approved make for this item" : null });
    }

    const lowConfidence = r.confidence != null && r.confidence < 0.7;
    let status;
    let reason;
    if (params.some((p) => p.result === "mismatch" && p.parameter !== "Make")) {
      status = "Not compliant";
      reason = params.filter((p) => p.result === "mismatch").map((p) => p.parameter + ": needs " + p.required + ", product has " + p.product).join("; ");
    } else if (!sku) {
      status = "Needs review";
      reason = "No product matched in the price lists";
    } else if (brandFlag) {
      status = "Needs review";
      reason = brandFlag.text;
    } else if (params.filter((p) => p.parameter !== "Make").length === 0) {
      status = "Needs review";
      reason = "The tender line states no parameters code can compare; check the specification";
    } else if (params.some((p) => p.result === "unknown")) {
      status = "Needs review";
      reason = params.filter((p) => p.result === "unknown").map((p) => p.parameter + " not in catalogue").join("; ");
    } else if (lowConfidence) {
      status = "Needs review";
      reason = "AI was unsure this is the same product (confidence " + r.confidence.toFixed(2) + ")";
    } else {
      status = "Compliant";
      reason = "All stated parameters match the catalogue entry";
    }
    return {
      item: r.item,
      description: r.description,
      page: r.page,
      sku: sku ? sku.sku : null,
      skuDescription: sku ? sku.description : null,
      source: sku ? sku.source || "price list" : null,
      confidence: r.confidence == null ? null : r.confidence,
      status: status,
      reason: reason,
      params: params,
    };
  });
}

// The overall Bid Readiness status, counts and a prioritized action list. Status rules:
//   any eligibility fail, required document Missing/Expired, OEM conflict/missing (required),
//   or Not-compliant BOQ line                                      → Potential disqualification
//   else anything unknown / Needs review / unmatched               → Review required
//   else                                                           → Ready for human review
function computeReadiness(opts) {
  const { eligibility, documents, oem, compliance, boqTotals } = opts;
  const actions = [];
  let passed = 0;
  let failed = 0;
  let review = 0;
  const add = (priority, area, text, page, quote) => actions.push({ priority: priority, area: area, text: text, page: page == null ? null : page, quote: quote || null });

  for (const e of eligibility || []) {
    // The eligibility rule only knows the firm profile's MAFs. An uploaded, checked letter for
    // this bid settles that clause; a letter still being checked turns a fail into a review.
    if (e.type === "oem_authorization" && e.result === "fail" && oem && (oem.status === "verified" || oem.status === "needs_review")) {
      if (oem.status === "verified") passed++;
      else {
        review++;
        add(2, "Eligibility", e.label + ": firm profile has no matching MAF, but an uploaded letter (" + oem.letterFile + ") may cover it. " + oem.reason, e.page, e.quote);
      }
      continue;
    }
    if (e.result === "pass") passed++;
    else if (e.result === "fail") {
      failed++;
      add(1, "Eligibility", e.label + ": " + e.reason, e.page, e.quote);
    } else if (e.result === "unknown") {
      review++;
      add(2, "Eligibility", e.label + ": " + e.reason, e.page, e.quote);
    }
  }
  for (const d of documents || []) {
    if (d.status === "Verified") passed++;
    else if (d.status === "Not applicable") continue;
    else if ((d.status === "Missing" || d.status === "Expired") && d.requirement === "required") {
      failed++;
      add(1, "Documents", d.name + ": " + (d.action || d.reason), d.page, d.quote);
    } else {
      review++;
      add(2, "Documents", d.name + ": " + (d.action || d.reason), d.page, d.quote);
    }
  }
  // The OEM check counts on its own only when the document list doesn't already include it.
  if (oem && oem.status !== "not_required" && !(documents || []).some((d) => d.docType === "oem_authorization")) {
    if (oem.status === "verified") passed++;
    else if (oem.status === "conflict" || (oem.status === "missing" && oem.requirement === "required")) {
      failed++;
      add(1, "OEM authorization", oem.reason, oem.page, oem.quote);
    } else {
      review++;
      add(2, "OEM authorization", oem.reason, oem.page, oem.quote);
    }
  }
  for (const c of compliance || []) {
    if (c.status === "Compliant") passed++;
    else if (c.status === "Not compliant") {
      failed++;
      add(1, "Technical", "Item " + c.item + ": " + c.reason, c.page, null);
    } else {
      review++;
      add(3, "Technical", "Item " + c.item + ": " + c.reason, c.page, null);
    }
  }

  const status = failed > 0 ? "Potential disqualification" : review > 0 ? "Review required" : "Ready for human review";
  actions.sort((a, b) => a.priority - b.priority);
  return {
    status: status,
    counts: { passed: passed, failed: failed, review: review },
    criticalDocuments: (documents || []).filter((d) => (d.status === "Missing" || d.status === "Expired") && d.requirement === "required").map((d) => d.name),
    technicalMismatches: (compliance || []).filter((c) => c.status === "Not compliant").map((c) => "Item " + c.item + ": " + c.reason),
    unverifiedClauses: (eligibility || []).filter((e) => e.result === "unknown").map((e) => e.label + ": " + e.reason),
    actions: actions,
    boqTotal: boqTotals && boqTotals.bidTotal ? boqTotals.bidTotal : null,
    marginPct: boqTotals ? boqTotals.marginPct : null,
  };
}


// Ties the plain-code steps together once the AI has answered. Uses functions from
// verifyQuotes.js, rules.js, matchChecks.js, pricing.js, verdict.js and readiness.js, so the
// n8n "Decide" node contains those files followed by this one.

// BOQ item numbers can repeat across sections ("1" under each heading); make them unique
// so every line keeps its own SKU match.
function uniqueItems(rows) {
  const seen = new Map();
  return (rows || []).map((r) => {
    const base = String(r.item == null || r.item === "" ? "?" : r.item).trim();
    const n = (seen.get(base) || 0) + 1;
    seen.set(base, n);
    return Object.assign({}, r, { item: n === 1 ? base : base + " (" + n + ")" });
  });
}

// input: { pages, clauses, boqRows, matches, priceRows, firm, today,
//          docRequirements?, supportingFiles?, supportingAi? }
function finalizeResult(input) {
  const clauses = verifyQuotes(input.pages, input.clauses || []);
  const eligibility = evaluateEligibility(clauses, input.firm, input.today);
  const approvedGroups = clauses
    .filter((c) => c.type === "approved_makes" && c.verified)
    .flatMap((c) => (c.values && c.values.items) || []);
  // Verify each BOQ line is on its page, then read its printed unit and quantity in code.
  const boqRows = readBoqLines(input.pages, verifyQuotes(input.pages, input.boqRows || []));
  const checked = checkMatches(boqRows, input.matches || [], input.priceRows, approvedGroups);
  const boq = priceBoq(checked, input.firm);
  const verdict = decide(eligibility, boq, input.firm);

  // Bid Readiness: documents, OEM authorization, technical compliance, overall status.
  const docRequirements = verifyQuotes(input.pages, input.docRequirements || []);
  const supportingDocs = checkSupportingDocs(input.supportingFiles || [], input.supportingAi || []);
  const oem = checkOemAuthorization({
    clauses: clauses,
    docRequirements: docRequirements,
    supportingDocs: supportingDocs,
    firm: input.firm,
    today: input.today,
    tenderRef: tenderReference(input.pages),
    boqDescriptions: boqRows.map((r) => r.description),
  });
  const documents = evaluateDocuments({ docRequirements: docRequirements, supportingDocs: supportingDocs, firm: input.firm, today: input.today, oem: oem });
  const compliance = technicalCompliance(checked, input.priceRows);
  const summary = computeReadiness({ eligibility: eligibility, documents: documents, oem: oem, compliance: compliance, boqTotals: boq.totals });

  return {
    verdict: verdict,
    eligibility: eligibility,
    boq: boq,
    readiness: {
      summary: summary,
      documents: documents,
      oem: oem,
      compliance: compliance,
      supportingDocs: supportingDocs.map((d) => ({ fileName: d.fileName, readable: d.readable, docType: d.docType, title: d.title, problem: d.problem, fields: d.fields, unverifiedFields: d.unverifiedFields })),
      tenderReference: tenderReference(input.pages),
    },
    meta: { pageCount: input.pages.length, firmName: input.firm.name || null },
  };
}


const body = $('Webhook').first().json.body;
const eligibilityAnswer = readGeminiJson($('Gemini: eligibility').first().json, 'Reading eligibility clauses');
const boqRows = $('A4 request').first().json.boqRows;
const matches = readGeminiJson($('Gemini: match SKUs').first().json, 'Matching SKUs').matches;
const files = body.supportingDocs || [];
const readable = files.filter((d) => !d.unreadable);
